# Compute largest t in [t_min, t_max] s.t. H1 > H2 * (1-p)^(-t)
# Equivalent condition: H1/H2 > q^{-t}
if H2 <= 0.0:
    return (False, None)
ln_ratio = math.log(H1 / H2)
ln_inv_q = math.log(1.0 / q)
# If ln_ratio <= 0, then H1 <= H2 and no t >= 0 works
if ln_ratio <= 0:
    # Ensure difficulty (no trivial shortcuts): inequality should fail at t_min
    if H1 > H2 / (q ** t_min):
        return (False, None)  # contradicts ln_ratio <= 0
    return (True, -1)
