candidate = min(t_allowed, t_max)
if candidate < t_min:
    # No t in range
    # Difficulty check: ensure inequality indeed fails at t_min
    if H1 > H2 / (q ** t_min):
        return (False, None)
    return (True, -1)
# Difficulty enforcement: ensure interior threshold (not trivial at t_max)
# i.e., inequality holds at candidate but fails at candidate+1 (if within range)
holds_cand = H1 > H2 / (q ** candidate)
if not holds_cand:
    return (False, None)
if candidate + 1 <= t_max:
    fails_next = H1 <= H2 / (q ** (candidate + 1))
    if not fails_next:
